def choose_move(observation):
    def is_num(x):
        return isinstance(x, (int, float)) and not isinstance(x, bool)

    def pos_of(obj):
        if isinstance(obj, dict):
            for k in ("position", "pos", "loc", "location", "xy", "coord", "coords"):
                v = obj.get(k)
                p = pos_of(v)
                if p is not None:
                    return p
            if "x" in obj and "y" in obj and is_num(obj.get("x")) and is_num(obj.get("y")):
                return [obj.get("x"), obj.get("y")]
        elif isinstance(obj, (list, tuple)) and len(obj) >= 2 and is_num(obj[0]) and is_num(obj[1]):
            return [obj[0], obj[1]]
        return None

    def first_pos(container):
        if isinstance(container, dict):
            p = pos_of(container)
            if p is not None:
                return p
            for v in container.values():
                p = first_pos(v)
                if p is not None:
                    return p
        elif isinstance(container, (list, tuple)):
            for item in container:
                p = pos_of(item)
                if p is not None:
                    return p
                p = first_pos(item)
                if p is not None:
                    return p
        return None

    def collect_positions(obj, out, limit=200):
        if len(out) >= limit:
            return
        p = pos_of(obj)
        if p is not None:
            out.append(p)
            return
        if isinstance(obj, dict):
            for v in obj.values():
                collect_positions(v, out, limit)
                if len(out) >= limit:
                    return
        elif isinstance(obj, (list, tuple)):
            for item in obj:
                collect_positions(item, out, limit)
                if len(out) >= limit:
                    return

    def sign(v):
        return (v > 0) - (v < 0)

    def clamp01(v):
        return 1 if v > 0 else (-1 if v < 0 else 0)

    def best_step_toward(src, dst, legal=None):
        dx = clamp01(dst[0] - src[0])
        dy = clamp01(dst[1] - src[1])
        cand = [[dx, dy]]
        if dx != 0 and dy != 0:
            cand += [[dx, 0], [0, dy]]
        cand += [[dx, dy], [dx, 0], [0, dy], [0, 0]]
        if legal:
