        for key in ("resources", "resource", "food", "goals", "targets", "target", "objects", "items", "points", "cells", "territory", "frontier", "enemies", "enemy", "opponents", "opponent", "players"):
            v = observation.get(key)
            if v is not None:
                pools.append((key, v))
    else:
        pools.append(("obs", observation))

    resources = []
    threats = []
    objectives = []
    misc = []

    for key, v in pools:
        tmp = []
        collect_positions(v, tmp)
        if not tmp:
            continue
        lk = key.lower()
        if any(w in lk for w in ("resource", "food", "item", "goal", "target")):
            resources.extend(tmp)
        elif any(w in lk for w in ("enemy", "opponent", "threat")):
            threats.extend(tmp)
        elif any(w in lk for w in ("territory", "frontier", "cell", "point")):
