        d = abs(p[0] - me[0]) + abs(p[1] - me[1])
        if best_rd is None or d < best_rd:
            best_rd = d
            nearest_target = p

    if nearest_threat is not None and (best_td is not None and (best_rd is None or best_td <= best_rd)):
        mv = best_step_away(me, nearest_threat, legal)
        if mv != [0, 0]:
            return mv

    if nearest_target is not None:
        mv = best_step_toward(me, nearest_target, legal)
        if mv != [0, 0]:
            return mv

    # Fallbacks: move toward center or stay.
    if isinstance(observation, dict):
