            if isinstance(v, (list, tuple)) and len(v) >= 2 and is_num(v[0]) and is_num(v[1]):
                center = [v[0] // 2, v[1] // 2]
                mv = best_step_toward(me, center, legal)
                if mv != [0, 0]:
                    return mv

    return [0, 0]

